package com.acrenex.app.activities;
import android.content.Intent;import android.database.Cursor;import android.os.Bundle;import android.widget.LinearLayout;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.security.AuthManager;import com.acrenex.app.utils;import com.google.android.material.button.MaterialButton;
public class ServiceRequestActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Citizen Services","Department-routed service requests with transparent status tracking.");DatabaseManager m=new DatabaseManager(this);String uid=new AuthManager(this).getUserId();Cursor c=m.getDatabase().rawQuery("SELECT service_code,service_name,department,status,updated_at,remarks FROM service_requests WHERE applicant_id=? ORDER BY updated_at DESC",new String[]{uid});try{if(c.moveToFirst())do{LinearLayout box=utils.column(this);utils.row(box,this,"Service",c.getString(1));utils.row(box,this,"Department",c.getString(2));utils.row(box,this,"Status",c.getString(3));utils.row(box,this,"Updated",c.getString(4));box.addView(utils.text(this,c.getString(5),12,utils.MUTED,false));utils.addCard(root,box,this);}while(c.moveToNext());else root.addView(utils.text(this,"No service request is linked to this profile yet.",14,utils.MUTED,false));}finally{c.close();}MaterialButton b1=utils.button(this,"Open Application Status");root.addView(b1);b1.setOnClickListener(v->startActivity(new Intent(this,ApplicationStatusActivity.class)));utils.setScreenContentView(this, root);}
}
